import { useState } from 'react'
import { Menubar } from 'moru-ui'

export function DocumentMenu() {
  const [status, setStatus] = useState('Untitled document')

  return (
    <div>
      <Menubar
        aria-label="Document actions"
        menus={[
          {
            id: 'file',
            label: 'File',
            items: [
              {
                id: 'new',
                label: 'New document',
                onSelect: () => setStatus('New document created.'),
              },
              {
                id: 'save',
                label: 'Save draft',
                onSelect: () => setStatus('Draft saved in this example.'),
              },
            ],
          },
          {
            id: 'help',
            label: 'Help',
            items: [
              {
                id: 'about',
                label: 'About',
                onSelect: () => setStatus('Moru document menu example.'),
              },
            ],
          },
        ]}
      />
      <p role="status">{status}</p>
    </div>
  )
}

