interface MenubarMenu {
  id: string
  label: string
  disabled?: boolean
  items: NavigationAction[]
}

interface MenubarProps {
  menus: MenubarMenu[]
  disabled?: boolean
  size?: 'sm' | 'md' | 'lg'
  className?: string
  'aria-label'?: string
}

